fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Since a and b have the same length, get their length once
    let n = a.len();

    // Pre-allocate output vector with capacity n for efficiency
    let mut result = Vec::with_capacity(n);

    // Iterate over indices and perform bitwise OR on corresponding elements
    for i in 0..n {
        result.push(a[i] | b[i]);
    }

    result
}